draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // couch
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = '#ccc';
  ctx.beginPath();
  ctx.rect(W/2-100, H/2-20, 200, 50);
  ctx.fill();
  ctx.stroke();

  // dog
  ctx.lineWidth = 3;
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+20+Math.sin(t)*20, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+40+Math.sin(t)*20);
  ctx.lineTo(W/2-20, H/2+60+Math.sin(t)*20);
  ctx.lineTo(W/2+20, H/2+60+Math.sin(t)*20);
  ctx.stroke();

  // caught
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+80);
  ctx.lineTo(W/2, H);
  ctx.stroke();

  // guilty
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Oops!', W/2, H/2+100+Math.sin(t)*10);

  ctx.restore();
}
